      }
    }
    var legs = legInsts.length ? { desc: g.box([1, 1, 1], [0, 0, 0]), finish: 'leg', instances: legInsts } : null

    // 5. FRAME WEB-BOLTS — vertical hex bolt pairs every 1.2 m down each rail's mid-wall, following the
    // surface normal so an inclined run keeps them on the tilted wall. The pair closes up on a shallow wall so both
    // heads stay 3 mm inside it (the wall runs -0.005 .. FB); a 0.17 m belt keeps its 0.04. Floored above 0: the
    // pair loop below steps by 2 * bGap.
    var bSpace = 1.2, bZ = hw + 0.013, yMid = FB / 2, br = 0.012, bH = 0.01
    var bGap = Math.max(0.001,Math.min(0.04, -0.005 - 0.003 - br - yMid, yMid - br - 0.003 - FB))
    var pathLen = 0
    for (var i = 1; i < path.length; i++) pathLen += Math.hypot(path[i][0] - path[i - 1][0], path[i][1] - path[i - 1][1])
    // position + normal at an arc-length s, interpolated between points (a straight belt's filleted path is
    // only 2 corners, so nearest-point would clump the bolts at the ends).
    function sampleAt(s) {
      var acc = 0
      for (var j = 1; j < path.length; j++) {
        var dx = path[j][0] - path[j - 1][0], dy = path[j][1] - path[j - 1][1], seg = Math.hypot(dx, dy)
        if (acc + seg >= s || j === path.length - 1) {
          var t = seg > 1e-9 ? (s - acc) / seg : 0, l = seg || 1
          return { x: path[j - 1][0] + dx * t, y: path[j - 1][1] + dy * t, nx: -dy / l, ny: dx / l }
        }
        acc += seg
      }
      return { x: path[0][0], y: path[0][1], nx: 0, ny: 1 }
    }
    if (p.frameRails !== false) { // no frame ⇒ no web-bolts (the leg bolts still stand)
      var nB = Math.max(2, Math.round(pathLen / bSpace))
      for (var bi = 0; bi < nB; bi++) {
        var smp = sampleAt(((bi + 0.5) / nB) * pathLen)
        for (var bs = -1; bs <= 1; bs += 2) {
          for (var bd = -bGap; bd <= bGap; bd += 2 * bGap) hexAt(smp.x + smp.nx * (yMid + bd), smp.y + smp.ny * (yMid + bd), bs * bZ, br, bH, 'z')
        }
      }
    }
    var bolts = hexInsts.length ? { desc: hexTemplate, finish: 'bolt', instances: hexInsts } : null

    // stable emit order — the host reconciles instanced banks by index — dropping the parts a toggle removed.
    var parts = [bed]
    if (bedWraps) parts.push(bedWraps)
    if (frame) parts.push(frame)
    if (frameBends) parts.push(frameBends)
    if (guards) parts.push(guards)
    if (guardBends) parts.push(guardBends)
    if (legs) parts.push(legs)
    if (bolts) parts.push(bolts)
    // hole panels LAST: they come and go with the sensors in the scene, and the host reconciles instanced banks by
    // index, so appending them leaves every other part's bank where it was
    for (var hpi = 0; hpi < holeParts.length; hpi++) parts.push(holeParts[hpi])
    // the mitre fills after them, for the same reason: they come and go with the junctions
    if (guardMitreFill) parts.push(guardMitreFill)
    if (railFills.length) parts.push({ desc: g.merge.apply(g, railFills), finish: 'frame' })
    return parts
  },
  react(ctx) {
    // Tag precedence: speedTag (REAL in) replaces the speed param as the commanded speed; runTag (BOOL)
    // gates it to 0, but ONLY while a controller actually drives the tag (ctx.tagDriven, output ownership) —
    // undriven, the authored speed rules; runningTag (BOOL out) = effective speed ≠ 0, written on every call.
    // the unit the conveyor is set up in: everything below this line is m/s
    const cmd = commandedSpeed(ctx)
    const fpm = cmd.fpm, commanded = cmd.commanded
    const running = ctx.tagDriven(ctx.params.runTag) ? ctx.readTag(ctx.params.runTag) : true
    const s = rampedSpeed(ctx, drive, cmd, running ? commanded : 0)
    // the readout the Inspector shows for 'speed' while a setpoint tag owns it: the EFFECTIVE value,
    // gates and all, not the raw setpoint (a runTag holding this at 0 must not read as the commanded rate)
    reportSpeed(ctx, fpm, s)
    if (ctx.params.runningTag) ctx.writeTag(ctx.params.runningTag, s !== 0)
    // drive feedback: the velocity as a share of the speed at 30, an encoder pulse and the odometer
    publishDrive(ctx, drive, cmd, s)
    // flow axis = the part's local +X in world space; the host redistributes this speed along each segment's
    // own tangent, so cargo is carried up/over an incline too.
    ctx.setSurfaceVelocity({ x: ctx.forward.x * s, y: 0, z: ctx.forward.z * s })
    // the next tick is needed only while the drive ramps or counts travel (conveyorDrive.js)
    driveAgain(ctx, drive, running ? commanded : 0)
  },
})

// Blade Stop — a pop-up blade that rises through the belt to stop cargo. The blade sections (middle +
// corners) ride a prismatic 'raise' joint; the housing and the pneumatic cylinders stay static, so the corner
// guide rods sit sheathed inside the cylinders and slide up through them on raise. 'airPressureHeight' is the
// mount height of the whole moving assembly above the housing, so the blade rest top sits at
// airPressureHeight + HOUSING_TOP (−0.05 at the 0.07 default). 'raiseHeight' is an absolute top height, so
// the joint commands raiseHeight − restTop; its 0.04 default is a real stop's rise. The guide rods are authored
// for a 0.06 raise (0.108 m of travel), and a longer stroke lengthens the rods and cylinders to match (geometry()).
// Driven by an authored 'active' toggle, or by a PLC bool tag while a program drives it.
//
// This is the part's source. `npm run build-parts` writes behavior.ts (this script as the app ships it, without
// `manifest` and `rig()`) and rig.json (the manifest, with the rig compiled from rig()).
//
// The shapes are kept in native units. geometry() scales them by S and maps a native z in two bands: |z| ≤ 1 (the
// middle sections) stretches to ±cornerZ, and beyond that (the corner nodes) keeps its size and slides out with it.

const r8 = (n) => Math.round(n * 1e8) / 1e8 // derived constants at 8 decimals, so 0.07 stays 0.07
const S = 0.45 // native → metres
const NATIVE_TOP = 0.2494 // blade/base top in native units
const NATIVE_BLADE_X = 0.1036 // blade centreline in native units
const LOWERED_TOP = -0.05 // blade-top rest height (below the belt surface)
const HOUSING_TOP = -0.12 // housing top pinned under the surface (clears every roller class)
const RAISE_MAX = 0.5 // raiseHeight's max
// The corner guide rods sink about 0.119 m into the static cylinders when both share the blade's rest frame.
// Their length is authored for a 0.06 raiseHeight (0.108 m of travel from the rest top); a longer raise
// lengthens the rods and cylinders.
const RODS_RAISE = 0.06
const RAISE_DEFAULT = 0.04 // a typical blade stop's rise: 20 mm to 1-7/8 in above the roller top
// Mount height of the whole moving assembly above the housing. The blade rest top = airPressureHeight + HOUSING_TOP.
const AIR_DEFAULT = r8(LOWERED_TOP - HOUSING_TOP)
const X0 = r8(-NATIVE_BLADE_X * S) // shifts the blade centreline to x = 0
const BLADE_Y = r8(LOWERED_TOP - S * NATIVE_TOP) // the blade's native origin at rest, in bladeRoot's frame
const BASE_Y = r8(HOUSING_TOP - S * NATIVE_TOP) // the housing's native origin
// Track-snapping onto a bed fits `width` to the host's usable width; this default is a free-standing drop's,
// the full 1.524 m belt width.
const WIDTH_DEFAULT = 1.524
// cornerZ = width/2 − S·0.2, floored at S·0.01
const CORNER_REACH = r8(S * 0.2)
const CORNER_MIN = r8(S * 0.01)
const ROD_TRAVEL = r8(RODS_RAISE - LOWERED_TOP) // the travel the rods are authored for

const RAISE_SECONDS = 0.15 // travel time lowered↔raised
let raised = null // 0 lowered .. 1 raised; seeded from 'active' on the first step, then chases
let active = false // runtime state — follows the 'active' param and a Use/click (pilot mode)
let lastActive // adopt the Inspector 'active' toggle whenever it changes

definePart({
  interactive: true, // a Use/click raises/lowers the blade
  useParam: 'active', // the hand state is the param: the state a run starts from. The Inspector sets it; Use never writes it
  joints: ['raise'],
  params: {
    width: { type: 'number', default: WIDTH_DEFAULT, min: 0.1, max: 2, step: 0.05, label: 'Width (m)', desc: 'Blade width across the lane. Size it to span the conveying surface, or cargo rides past the end of the blade.' },
    active: { type: 'boolean', default: false, label: 'Active', group: 'Start state', desc: 'Raise the blade to stop cargo. This is the state it starts in; Use cycles it by hand. While a program drives the tag below, that program owns it instead.' },
    raiseHeight: { type: 'number', default: RAISE_DEFAULT, min: 0.02, max: RAISE_MAX, step: 0.01, label: 'Raise height (m)', desc: 'How far the blade top stands above the conveying surface once raised - the height of the stop cargo meets. At rest the top parks just below the surface, so raising this lengthens the stroke.' },
    airPressureHeight: { type: 'number', default: AIR_DEFAULT, min: 0, max: 0.12, step: 0.005, label: 'Air pressure height (m)', desc: 'Mount height of the whole moving assembly - pistons, blade and rods together - above the housing. Trim it to sit the mechanism correctly against a particular deck; it shifts the REST position, not the stroke.' },
    // autoWhenDriven: this tag COMMANDS the blade (the step's auto gate reads it), so a program driving it
    // owns the device — the pilot prompt shows "In auto - PLC controlled" instead of a dead "Use".
    tag: { type: 'tag', dir: 'in', stType: 'BOOL', autoWhenDriven: true, default: '', label: 'Raise tag (true raises the blade)', group: 'Comms', desc: 'Raise the blade from the program. While a program drives this tag it OWNS the blade stop, so a hand Use in pilot mode is refused with "In auto - PLC controlled".' },
  },
  // Everything visible. Shapes are in native units and mapped to metres here: x·S + X0, y·S + the piece's
  // mount, and z by mz() — |z| ≤ 1 is the middle, stretched to ±cornerZ; past 1 is corner hardware, rigid,
  // sliding out with cornerZ. Every box has the model's 0.002 bevel. Housing + cylinders sit on the part root
  // (static); the blade and its hardware ride 'bladeRoot'.
  geometry(g, p) {
    var B = 0.002
    var width = typeof p.width === 'number' ? p.width : WIDTH_DEFAULT
    var apH = typeof p.airPressureHeight === 'number' ? p.airPressureHeight : AIR_DEFAULT
    var cz = Math.max(width / 2 - CORNER_REACH, CORNER_MIN)
    // Cylinders are sized to the stroke. The model's cylinder + guide rods are authored for a ROD_TRAVEL
    // (rest top to raiseHeight); a longer one would pull the rods clean out of the cylinders and leave the blade
    // floating. So the extra travel lengthens the rods and the cylinder body DOWNWARD by the same amount (same
    // sheath at full raise as the default), stopping 1 cm above the housing's floor slab.
    var raise = typeof p.raiseHeight === 'number' ? p.raiseHeight : RAISE_DEFAULT
    var travel = raise - (apH + HOUSING_TOP)
    var room = apH + (0.6124 - 0.3385) * S - 0.01
    var ext = Math.max(0, Math.min(travel - ROD_TRAVEL, room)) / S // native units
    var mz = function (z) { var a = Math.abs(z); return a <= 1 ? z * cz : (z < 0 ? -1 : 1) * (cz + (a - 1) * S) }
    var X = function (x) { return x * S + X0 }
    var D2R = Math.PI / 180
    // a chamfered box from native extents at a mount height (x, y scaled; z through mz: every box ends in the rigid
    // corner region, so its chamfer is B·S all round)
    var box = function (list, yOff, x0, x1, y0, y1, z0, z1, square) {
      var a = [X(x0), y0 * S + yOff, mz(z0)], b = [X(x1), y1 * S + yOff, mz(z1)]
      list.push(g.bevelBox([b[0] - a[0], b[1] - a[1], b[2] - a[2]], [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2, (a[2] + b[2]) / 2], B * S, square))
    }
    // a round rod along y about native (x, z): profile [r, y] in native units, 8 facets, smooth
    var rodY = function (list, yOff, x, z, prof) {
      list.push(g.lathe(prof.map(function (q) { return [q[0] * S, q[1] * S] }), { axis: 'y', center: [X(x), yOff, mz(z)], segments: 8 }))
    }
    // a hex bolt along z at native (x, y): profile [r, z] for the +z side; the −z side is its mirror, walked the
    // other way so the outside stays on the right
    var hexZ = function (list, yOff, x, y, prof, deg, side) {
      var mapped = prof.map(function (q) { return [q[0] * S, mz(side * q[1])] })
      if (side < 0) mapped.reverse()
      list.push(g.lathe(mapped, { axis: 'z', center: [X(x), y * S + yOff, 0], segments: 6, startAngle: deg * D2R, smooth: false }))
    }
    // a 45° flare strip where a panel meets the slab or rail, the full run long, facing away from corner c
    var flare = function (list, yOff, p, q, c) {
      var s = g.surface(), z0 = mz(-1.15), z1 = mz(1.15)
      var P = [X(p[0]), p[1] * S + yOff], Q = [X(q[0]), q[1] * S + yOff], C = [X(c[0]), c[1] * S + yOff]
      var a = s.vertex(P[0], P[1], z0), b = s.vertex(Q[0], Q[1], z0), cc = s.vertex(Q[0], Q[1], z1), d = s.vertex(P[0], P[1], z1)
      // a→b→cc→d faces the right-hand side of P→Q; keep that if it points away from c, else wind it the other way
      var away = (P[0] - C[0]) * (Q[1] - P[1]) - (P[1] - C[1]) * (Q[0] - P[0]) > 0
      if (away) s.quad(a, b, cc, d)
      else s.quad(a, d, cc, b)
      list.push(s.build())
    }

    var steel = [], plate = [], belt = []
    // housing: bottom slab, the core wall (light panel faces both sides), the top rail on the +x side, the black
    // strip on top, and an end plate closing each end; faces meeting a neighbour flush stay square
    box(steel, BASE_Y, 0, 0.4, -0.6606, -0.6124, -1.15, 1.15)
    box(steel, BASE_Y, 0.2682, 0.4, 0.2083, 0.2293, -1.15, 1.15, ['x-', 'y+'])
    box(plate, BASE_Y, 0.2, 0.2662, -0.6124, 0.2293, -1.15, 1.15, ['y-', 'y+'])
    box(belt, BASE_Y, 0.2, 0.4, 0.2293, 0.2494, -1.152, 1.152, ['y-'])
    flare(plate, BASE_Y, [0.2662, -0.6104], [0.2682, -0.6124], [0.2662, -0.6124])
    flare(plate, BASE_Y, [0.2, -0.6104], [0.198, -0.6124], [0.2, -0.6124])
    flare(plate, BASE_Y, [0.2662, 0.2063], [0.2682, 0.2083], [0.2662, 0.2083])
    box(steel, BASE_Y, 0, 0.4, -0.6606, 0.2494, 1.15, 1.2)
    box(steel, BASE_Y, 0, 0.4, -0.6606, 0.2494, -1.2, -1.15)
    // pneumatic cylinders: two black blocks, the round body between them, a cap on top (the bottom block and the
    // body reach down by ext for a long stroke)
    var airY = BASE_Y + apH
    for (var side = -1; side <= 1; side += 2) {
      var zlo = side > 0 ? 1.0463 : -1.1527, zhi = side > 0 ? 1.1527 : -1.0463
      box(belt, airY, 0.0506, 0.1569, -0.1177, -0.0761, zlo, zhi)
      box(belt, airY, 0.0506, 0.1569, -0.3385 - ext, -0.2969 - ext, zlo, zhi)
      rodY(plate, airY, 0.10375, side * 1.0995, [[0, -0.3042 - ext], [0.0431, -0.3042 - ext], [0.0431, -0.1104], [0, -0.1104]])
      rodY(steel, airY, 0.10375, side * 1.09945, [[0, -0.083], [0.02615, -0.083], [0.02615, -0.0652], [0.02405, -0.0632], [0, -0.0632]])
    }

    var bBlade = [], bSteel = [], bPlate = []
    box(bBlade, BLADE_Y, 0.0786, 0.1288, 0, 0.2461, -1.0843, 1.0843)
    for (var sd = -1; sd <= 1; sd += 2) {
      var zl = function (z0, z1) { return sd > 0 ? z0 : -z1 }, zh = function (z0, z1) { return sd > 0 ? z1 : -z0 }
      // the end post the blade is bolted to, and the clamp at its foot
      box(bSteel, BLADE_Y, 0.0786, 0.1288, -0.0437, 0.2462, zl(1.0877, 1.1113), zh(1.0877, 1.1113))
      box(bSteel, BLADE_Y, 0.086, 0.1214, -0.0561, -0.0111, zl(1.0758, 1.1232), zh(1.0758, 1.1232))
      // the guide rod down into the cylinder
      rodY(bPlate, BLADE_Y, 0.10375, sd * 1.09945, [[0, -0.3271 - ext], [0.01445, -0.3271 - ext], [0.01445, -0.0556], [0, -0.0556]])
      // the hex bolt through the clamp, and the two bolt heads on the post's outer face
      hexZ(bPlate, BLADE_Y, 0.10293, -0.03405, [[0, 1.0701], [0.00989, 1.0701], [0.01212, 1.0721], [0.01212, 1.1255], [0.00989, 1.1275], [0, 1.1275]], 49.8, sd)
      hexZ(bPlate, BLADE_Y, 0.10367, 0.21218, [[0, 1.1091], [0.01056, 1.1091], [0.01056, 1.1145], [0.00832, 1.1165], [0, 1.1165]], 10.8, sd)
      hexZ(bPlate, BLADE_Y, 0.10367, 0.02902, [[0, 1.1091], [0.01061, 1.1091], [0.01061, 1.1145], [0.00824, 1.1165], [0, 1.1165]], 32, sd)
    }

    var both = { doubleSided: true }
    var m = function (list) { return g.merge.apply(g, list) }
    return [
      Object.assign({ desc: m(steel), material: 'steel' }, both),
      Object.assign({ desc: m(plate), material: 'plate' }, both),
      Object.assign({ desc: m(belt), material: 'belt' }, both),
      Object.assign({ desc: m(bBlade), material: 'blade', link: 'bladeRoot' }, both),
      Object.assign({ desc: m(bSteel), material: 'steel', link: 'bladeRoot' }, both),
      Object.assign({ desc: m(bPlate), material: 'plate', link: 'bladeRoot' }, both),
    ]
  },
  step(ctx) {
    // Signal handoff: the tag commands the blade only while a controller actually drives it (the tag is an
    // attached program's output, ctx.tagDriven). Any other time the manual signal rules: the
    // 'active' param (adopted when toggled in the Inspector) or a pilot Use/click.
    if (ctx.params.active !== lastActive) { active = ctx.params.active; lastActive = ctx.params.active }
    if (ctx.used()) active = !active
    // auto wins by overwriting the hand latch (bumpless transfer): a press while owned is undone the same
    // tick, and when ownership releases the blade holds its last commanded state.
    if (ctx.tagDriven(ctx.params.tag)) active = ctx.readTag(ctx.params.tag)
    // the hand latch AFTER the auto gate — what the device is really doing, for the Inspector readout
    ctx.report('active', active)
    const want = active ? 1 : 0
    if (raised === null) raised = want
    raised = ctx.approach(raised, want, ctx.dt / RAISE_SECONDS)
    const restTop = ctx.params.airPressureHeight + HOUSING_TOP // −0.05 at the default mount
    ctx.joints.raise = (ctx.params.raiseHeight - restTop) * raised // blade top lands exactly at raiseHeight
  },
})

// Spawner — a hopper that emits a product: boxes by default, or any cargo part in the project. Demonstrates ctx.spawn
// by product: the behavior runs its own rate timer and emits an item every 60/boxesPerMinute seconds via
// ctx.spawn({ part, params }); the host creates that part's body at the part's pose + the given local offset, as if
// placed. A Box takes this part's own size, colour and mass settings (the part's id is still oip.box-spawner). Cargo
// drops at the exact spawn point (no positional scatter), so downstream handling (picks, aligned queues) sees a
// repeatable pose. A pilot "Use" toggles the feed (a runtime latch, so it resets on stop/reload). Optionally gated by
// a conveyor interlock (conveyorId → ctx.conveyorRunning) or a PLC run tag.
//
// A mixed stream: `mixAttribute` names a product attribute and `mixValues` the values handed out one per item, in
// order (or at random with Random order). They start as the item's marks (ctx.spawn `marks`), the way a label printed
// upstream does, so a scanner reads them and a program routes by them. The value list and the colour list advance
// together: item n takes value n and colour n, so a code can be seen by its colour.
//
// Release says what reopening the gate does.
// - Steady interval: a hopper, PACED. What the author sets is the INTERVAL BETWEEN items, so that is what a hold
//   preserves. The countdown keeps running while the gate is shut but floors at zero: a hold neither costs a period
//   nor banks one. Freeze it instead and every release pays out the remainder of an interval the hopper spent
//   standing still (in the PLC demo: ~2.7 s of empty lane at the top of every row); let it run unfloored and a long
//   hold banks a burst that all lands in one tick.
// - On each enable: a magazine, COMMANDED. Every enable re-arms it and it drops at once, then paces while the gate
//   stays open. That is what makes a command pulse shorter than one period dispense exactly one item, every time.
//   Carry the countdown across the hold instead and only the first pulse ever dispenses.

// random-size range, full box dimensions (m)
const SIZE_MIN = [0.4, 0.3, 0.3]
const SIZE_MAX = [0.8, 0.5, 0.5]

let countdown = 0 // seconds until the next spawn
let started = false // steady interval: arm the first item on the first eligible tick
let armed = false // on each enable: drop on the first eligible tick after every enable, not a period later
let colorIndex = 0
let usedOff = false
let spawned = 0

// Publish what this feed has dispensed, every tick (a display not republished goes blank): the infeed half
// of the line's numbers, which a despawner's count is the other half of - the two differ by the work in
// progress. It counts REQUESTS: past the physics engine's 10,240-body table a spawn is skipped, uncounted
// by the host but still counted here.
function publish(ctx) {
  ctx.display('spawned', spawned)
  if (ctx.params.countTag) ctx.writeNumber(ctx.params.countTag, spawned)
}

// parse "#rrggbb" → [r, g, b] in 0..1
function hexRgb(hex) {
  const h = (hex || '').replace('#', '')
  if (h.length < 6) return [1, 1, 1]
  const v = (i) => { const n = parseInt(h.slice(i, i + 2), 16); return Number.isFinite(n) ? n / 255 : 1 }
  return [v(0), v(2), v(4)]
}
// the product settings param's JSON object (`{"size":"400x300x220"}`), or {} when it is empty or malformed
function settingsOf(json) {
  try {
    const o = JSON.parse(json || '{}')
    return o && typeof o === 'object' && !Array.isArray(o) ? o : {}
  } catch {
    return {}
  }
}
// parse a comma-separated hex list → [[r,g,b], …]
function palette(csv) {
  return (csv || '').split(',').map((c) => c.trim()).filter((c) => c.length >= 6).map(hexRgb)
}
// parse a comma-separated value list: numbers as numbers, true / false as booleans, anything else as text
function valueList(csv) {
  return (csv || '').split(',').map((c) => c.trim()).filter((c) => c !== '').map((c) => {
    if (c === 'true' || c === 'false') return c === 'true'
    const n = Number(c)
    return Number.isFinite(n) ? n : c
  })
}

definePart({
  interactive: true, // a pilot "Use" toggles the feed
  params: {
    boxesPerMinute: { type: 'number', unit: '/min', default: 45, min: 0, max: 1000, step: 1, label: 'Feed rate', desc: 'Items per minute. 0 halts the feed without pausing the part, so the timer restarts cleanly when you raise it again.' },
    fixedRate: { type: 'boolean', default: true, label: 'Fixed rate (off = ±50% jitter)', desc: 'On, items arrive on an exact metronome. Off, each gap is randomised between half and one-and-a-half times the nominal period, which is what an untidy real feed looks like downstream.' },
    product: { type: 'string', product: true, settings: 'productSettings', default: 'oip.box', label: 'Product', desc: 'The cargo part every item is, from the parts in the project: dropped as if placed, with its own size, colour, mass and product attributes. Its settings show below it. A Box takes the size, colour and mass under Box instead.' },
    productSettings: { type: 'string', hidden: true, default: '', label: 'Product settings', desc: 'Settings of the chosen product, as JSON. Edited under Product.' },
    boxColor: { type: 'color', default: '#ffffff', label: 'Box color', group: 'Box', visibleWhen: { param: 'product', is: 'oip.box' }, desc: 'Tint for every spawned box. Ignored once the cycle list below is non-empty.' },
    boxColors: { type: 'color', list: true, default: '', label: 'Colors (cycle)', desc: 'Colors handed out one per item, in order, overriding the colour of the product (or the Box color). Useful for telling sorted lanes apart at a glance. Leave empty to use the single colour.' },
    mixAttribute: { type: 'string', default: '', label: 'Vary attribute', desc: 'A product attribute each item starts with, from the values below: a label code, a destination. A scanner reads it, and a program routes by it. Empty for none.' },
    mixValues: { type: 'string', default: '', label: 'Values (cycle)', desc: 'The values handed out one per item, comma-separated, in order: "1, 2, 2, 3". Numbers stay numbers, true and false are booleans, anything else is text. They advance with the colour cycle, so item n takes value n and colour n.' },
    randomColors: { type: 'boolean', default: false, label: 'Random order', desc: 'Give each item a colour and a value drawn at random from the cycle lists instead of walking them in order.' },
    length: { type: 'number', default: 0.6, min: 0.1, step: 0.05, label: 'Box length (m)', group: 'Box', visibleWhen: { param: 'product', is: 'oip.box' }, desc: 'Extent along local X of each spawned box. Ignored while Random size is on.' },
    width: { type: 'number', default: 0.4, min: 0.1, step: 0.05, label: 'Box width (m)', group: 'Box', visibleWhen: { param: 'product', is: 'oip.box' }, desc: 'Extent along local Z of each spawned box. Ignored while Random size is on.' },
    height: { type: 'number', default: 0.4, min: 0.1, step: 0.05, label: 'Box height (m)', group: 'Box', visibleWhen: { param: 'product', is: 'oip.box' }, desc: 'Extent along local Y of each spawned box. Ignored while Random size is on.' },
    randomSize: { type: 'boolean', default: false, label: 'Random size', group: 'Box', visibleWhen: { param: 'product', is: 'oip.box' }, desc: 'Give each box a random size and IGNORE the three dimensions above. The random range is fixed by the part (0.4-0.8 long, 0.3-0.5 high, 0.3-0.5 wide), not derived from them.' },
    mass: { type: 'number', default: 10, min: 0.5, max: 100, step: 0.5, label: 'Mass (kg)', group: 'Box', visibleWhen: { param: 'product', is: 'oip.box' }, desc: 'Mass given to every spawned box, whatever its size.' },
    disable: { type: 'boolean', default: false, label: 'Paused', desc: 'Stop spawning entirely. Use (C, or E while walking) is a separate hand stop: it pauses and resumes the feed during a run without changing this setting, and is cleared when the run stops.' },
    release: {
      type: 'enum', default: 'interval', label: 'Release',
      options: [{ value: 'interval', label: 'Steady interval' }, { value: 'enable', label: 'On each enable' }],
      desc: 'What reopening the gate (Paused, Use, the conveyor interlock, the run tag) does. Steady interval: items come at the feed rate and the gap since the last one is always kept, so a short pulse may drop nothing. On each enable: an item drops the moment the gate opens, then more at the feed rate while it stays open, so each pulse of the run tag dispenses one.',
    },
    keepSpacing: { type: 'boolean', default: false, visibleWhen: { param: 'release', is: 'interval' }, label: 'Keep spacing while held', desc: 'Hold the interval while the feed is held instead of letting it run down, so boxes dropped onto a conveyor that stops with this spawner (give both the same run tag) stay one pitch apart however often the pair stops.' },
    conveyorId: { type: 'partRef', default: '', label: 'Pause when conveyor stopped', desc: 'Interlock: while the named conveyor is stopped, this spawner holds. Wire that conveyor to the PLC and the feed gates itself, with no tag of its own.' },
    runTag: { type: 'tag', dir: 'in', stType: 'BOOL', onlyWhenDriven: true, default: '', label: 'Run tag (spawn only while true)', group: 'Comms', desc: 'Gate the feed from the program. Note this only takes over once a program actually DRIVES the tag - until then the spawner keeps running, so a merely-declared tag is not a stopped feed.' },
    countTag: { type: 'tag', dir: 'out', stType: 'DINT', default: '', label: 'Spawned count tag', group: 'Comms', desc: 'Running total of boxes this spawner has dispensed. Subtract the despawner counts to get the work in progress.' },
  },
  step(ctx) {
    const p = ctx.params
    if (ctx.used()) usedOff = !usedOff
    // hold while a linked conveyor is stopped, or while a controller DRIVES the run tag de-energized
    // (ctx.tagDriven = output ownership; gating on the tag NAME alone would stop the spawner the moment one
    // was typed).
    const stopped = !ctx.conveyorRunning(p.conveyorId) || (ctx.tagDriven(p.runTag) && !ctx.readTag(p.runTag))
    const onEnable = p.release === 'enable'
    if (p.disable || usedOff || stopped || p.boxesPerMinute <= 0) {
      // on each enable: held off = disarmed, so the next open is a fresh command
      if (onEnable) armed = false
      // steady interval: the interval runs on, floored at zero (see the note at the top). Floored is what makes this
      // safe for an interlock that STUTTERS: at most one item is ever due when the gate reopens, never a burst.
      // Keep spacing: a feed onto a conveyor that stops WITH it (the same gate) must not run its interval down, or
      // the first item after a hold lands on the one the stopped belt is still holding under the drop
      else if (!p.keepSpacing) countdown = Math.max(0, countdown - ctx.dt)
      publish(ctx)
      return
    }
    const period = 60 / p.boxesPerMinute
    // the first item drops on the first eligible tick, not after a full period: once per run for a steady interval,
    // after every enable for on each enable
    if (onEnable) {
      if (!armed) { armed = true; countdown = 0 }
    } else if (!started) { started = true; countdown = 0 }
    countdown -= ctx.dt
    const pal = palette(p.boxColors)
    const values = p.mixAttribute ? valueList(p.mixValues) : []
    let n = 0
    while (countdown <= 0 && n < 8) {
      countdown += p.fixedRate ? period : Math.max(ctx.dt, period * (0.5 + ctx.rng()))
      n++
      // one step or one draw per item for both lists, so item n takes colour n and value n (a stream with no values
      // draws exactly as it did before values existed)
      let ci = 0
      let vi = 0
      if (pal.length > 0 || values.length > 0) {
        if (p.randomColors) {
          const r = ctx.rng()
          ci = Math.floor(r * pal.length)
          vi = Math.floor(r * values.length)
        } else {
          ci = colorIndex % Math.max(1, pal.length)
          vi = colorIndex % Math.max(1, values.length)
          colorIndex++
        }
      }
      const color = pal.length > 0 ? pal[ci] : p.product === 'oip.box' ? hexRgb(p.boxColor) : undefined
      const marks = values.length > 0 ? { [p.mixAttribute]: values[vi] } : undefined
      if (p.product === 'oip.box') {
        const rnd = (i) => SIZE_MIN[i] + ctx.rng() * (SIZE_MAX[i] - SIZE_MIN[i])
        const size = p.randomSize ? [rnd(0), rnd(1), rnd(2)] : [p.length, p.height, p.width]
        ctx.spawn({ part: 'oip.box', params: { length: size[0], height: size[1], width: size[2] }, color: color, mass: p.mass, offset: [0, -0.2, 0], ...(marks ? { marks } : {}) })
      } else if (p.product) {
        // any other product drops as itself, with its settings from the Inspector; a colour only from the cycle list
        ctx.spawn({ part: p.product, params: settingsOf(p.productSettings), ...(color ? { color } : {}), offset: [0, -0.2, 0], ...(marks ? { marks } : {}) })
      } else {
        continue // no product: the feed paces on and drops nothing
      }
      spawned++
    }
    publish(ctx)
  },
})

// Box — a piece of authored cargo. Demonstrates the cargo geometry kind: the package geometry declares
// { kind: 'cargo', cargoKind: 'box' } and the host builds the part as one dynamic physics body sized/tinted
// from the params below (instanced batch render, gizmo grab, pilot carry). There is nothing to simulate
// here: cargo is passive payload, so react() is empty.

definePart({
  params: {
    // size drives both the render scale and the dynamic body's half-extents (centre origin). Each carries a
    // face handle, so a placed box shows a resize dot on all six faces; the host holds the opposite face.
    length: { type: 'number', default: 0.6, min: 0.1, step: 0.05, label: 'Length (m)', handle: { kind: 'face', axis: 'x' }, desc: 'Extent along local X. Drives the collision body as well as the visual, and the box is centred on its origin.' },
    width: { type: 'number', default: 0.4, min: 0.1, step: 0.05, label: 'Width (m)', handle: { kind: 'face', axis: 'z' }, desc: 'Extent along local Z. Drives the collision body as well as the visual.' },
    height: { type: 'number', default: 0.4, min: 0.1, step: 0.05, label: 'Height (m)', handle: { kind: 'face', axis: 'y' }, desc: 'Extent along local Y. Drives the collision body as well as the visual.' },
    mass: { type: 'number', default: 10, min: 0.5, max: 100, step: 0.5, label: 'Mass (kg)', desc: 'Physical mass. Heavier cargo is harder for a conveyor to accelerate and pushes lighter cargo out of the way.' },
    color: { type: 'color', default: '#ffffff', label: 'Color', desc: 'Tint over the cardboard texture. White leaves it untinted.' },
  },
  react() {
  },
})

// Despawner - a cargo sink, and the line's measuring point. Demonstrates ctx.zone / ctx.zoneAge /
// ctx.despawn: each tick it counts the cargo in its 'mouth' zone (all of it, or one product), adds up how long that
// cargo has existed, and removes it. From those two running sums it reports what this exit has done: the count, the rate, and
// the average cycle time (spawn to here). A PLC block tag pauses removal, so cargo accumulates at the gate.
//
// The numbers are published as displays, so they need no wiring to see, and can be shown on the part itself (the
// 'readout' plate, off by default); the tags are for a program or a project test that wants to act on them.

let total = 0
let ageSum = 0 // summed age of everything removed, sim seconds

definePart({
  params: {
    length: { type: 'number', default: 2, min: 0.2, max: 4, step: 0.1, label: 'Length (m)', desc: 'Local X extent of the volume that removes cargo. Cargo vanishes as soon as it is inside, so cover the full lane width or things slip past the edge.' },
    width: { type: 'number', default: 2, min: 0.2, max: 4, step: 0.1, label: 'Width (m)', desc: 'Local Z extent of the volume that removes cargo.' },
    height: { type: 'number', default: 1, min: 0.2, max: 4, step: 0.1, label: 'Height (m)', desc: 'Local Y extent of the volume that removes cargo.' },
    countOnly: { type: 'string', product: true, default: '', label: 'Count only', desc: 'Count just this product, so a tote carrying a case counts once. Everything in the mouth is still removed. (none) counts every body that goes in.' },
    showReadout: { type: 'boolean', default: false, label: 'Show readout', desc: 'Show the count, rate and cycle time on a plate above the volume. A viewing aid only: the displays and tags publish the same numbers either way.' },
    countTag: { type: 'tag', dir: 'out', stType: 'INT', default: '', label: 'Throughput count tag', group: 'Comms', desc: 'Running total of everything this despawner has removed, published for the program to read. It only ever climbs, so take differences over time to get a rate.' },
    rateTag: { type: 'tag', dir: 'out', stType: 'REAL', default: '', label: 'Throughput rate tag', unit: '/min', group: 'Comms', desc: 'Items removed per minute of simulated time, averaged over the whole run so far.' },
    cycleTag: { type: 'tag', dir: 'out', stType: 'REAL', default: '', label: 'Average cycle time tag', unit: 's', group: 'Comms', desc: 'Average time, in simulated seconds, from an item coming into being (spawned, or already in the scene when the run started) to its removal here. 0 until the first item arrives.' },
    blockTag: { type: 'tag', dir: 'in', stType: 'BOOL', default: '', label: 'Block tag (pause removal while true)', group: 'Comms', desc: 'While the program holds this true, nothing is removed and cargo backs up into the mouth - the way to model a downstream line that has stopped taking product.' },
  },
  step(ctx) {
    const p = ctx.params
    const blocked = p.blockTag ? ctx.readTag(p.blockTag) : false
    const n = ctx.zone('mouth')
    if (n > 0 && !blocked) {
      const only = p.countOnly ? { part: p.countOnly } : undefined
      total += only ? ctx.zone('mouth', only) : n
      ageSum += ctx.zoneAge('mouth', only)
      ctx.despawn('mouth')
    }
    const t = ctx.simTime + ctx.dt // sim time at the END of this tick, the one this tick's removals happened in
    const rate = (total / t) * 60
    const cycle = total > 0 ? ageSum / total : 0
    ctx.display('count', total)
    ctx.display('rate', rate)
    ctx.display('cycle', cycle)
    ctx.display('readout', total + ' done  ' + rate.toFixed(1) + '/min  ' + (total > 0 ? cycle.toFixed(1) + ' s' : '-'))
    if (p.countTag) ctx.writeNumber(p.countTag, total)
    if (p.rateTag) ctx.writeNumber(p.rateTag, rate)
    if (p.cycleTag) ctx.writeNumber(p.cycleTag, cycle)
  },
})

// Photo Eye - a photoelectric presence sensor, diffuse or retro-reflective (the package id still says diffuse:
// stored scenes and rooms name it). Demonstrates sensing (ctx.sense), an emissive detection LED (ctx.lamps), and
// a PLC presence tag. The lens emits a beam along local +Z; the host casts it against cargo each tick and
// hands back the nearest hit. Both modes come down to that one cast: the first target in the beam before Max range.
//
// The housing is the shared photoeye (_shared/sensorPhotoeye.js), drawn by geometry().
//
// This is the part's source. `npm run build-parts` writes behavior.ts (this script as the app ships it, with the
// _shared/ modules it imports joined in and `manifest` / `rig()` left out) and rig.json (the manifest, with the
// rig compiled from rig()).

// ---- from examples/parts/_shared/sensorOutlines.js ----
// a rounded-corner rectangle, for windows and panels
function rrect(x0, y0, x1, y1, r) {
  const pts = []
  for (const [cx, cy, a0] of [[x1 - r, y0 + r, -Math.PI / 2], [x1 - r, y1 - r, 0], [x0 + r, y1 - r, Math.PI / 2], [x0 + r, y0 + r, Math.PI]])
    for (let k = 0; k <= 3; k++) { const a = a0 + (k * Math.PI) / 6; pts.push([cx + r * Math.cos(a), cy + r * Math.sin(a)]) }
  return pts
}

// a 16-sided circle, for mounting holes
function circle(cy, cz, r) {
  const pts = []
  for (let k = 0; k < 16; k++) { const a = (k * Math.PI) / 8; pts.push([cy + r * Math.cos(a), cz + r * Math.sin(a)]) }
  return pts
}

// ---- from examples/parts/_shared/sensorPhotoeye.js ----
const PHOTOEYE = {
  halfX: 0.0225, // 45 mm wide
  back: -0.036,
  front: 0.037, // the lens face: SENSOR_EMIT_Z, the beam origin and the guard contact
  bodyY0: 0.036, // the housing's underside; the M8 plug hangs below it
  bodyY1: 0.15,
  height: 0.16, // SENSOR_HEIGHT: the pot on the top cap reaches it
  emitY: 0.1, // SENSOR_EMIT_Y, inside the lens window
  led: [0, 0.124, 0.034], // the detection LED, on the face above the window
}

// The photoeye's MOUNTING BRACKET, which bolts it to a conveyor's SIDE FRAME - with a guard or without one, and
// touching neither anywhere but where it is bolted.
//
// The guard mount seats the eye with its origin 20 mm below the deck and its lens face 20 mm out from the bed edge,
// over the frame's L-rail (examples/parts/belt-conveyor's rail template; the roller bed's is the same): a WALL whose
// face is 10 mm out from the bed edge, running down from 5 mm under the deck, a 5 mm top LIP reaching out to 30 mm at
// deck height, and - where the bed has one - a GUARD sheet standing on the rail 10..15 mm out (GUARD_THICKNESS).
// Measured outward from the bed edge (u, which is FRONT + 0.02 - z in part-local z), the bracket is:
//   - a SIDE PLATE on the housing's +X flank, bolted through its two holes. Its profile steps round the steel: from
//     the housing down to 3 mm over the lip it stays out past u 23 mm (clear of a guard's 15), past the lip it stays
//     out past the lip's 30 mm tip, and only well under the lip - below the axle heads studding the wall just under
//     it - does it step in to the wall;
//   - a TOE there, square across the beam, flat on the wall face (u 10..13 mm) and bolted to it.
// A floor stand bolts to the toe's face the same way (src/editor/demoScenes.ts EYE_STAND_*), so its numbers are
// transcribed there.
//
// A STOPGAP, and a deliberate copy: the rail's numbers above belong to the conveyor, and are repeated here only
// because a host cannot yet say what steel it offers. Retire this (and EYE_STAND_*) when conveyors publish their
// rail profile on their snap surface and the SDK's bracket helper draws from the seat a mount stores.
const PHOTOEYE_BRACKET = {
  gauge: 0.003, // the sheet
  width: 0.052, // the toe across the beam, from the plate: clear of the lens window by 7.5 mm
  wall: 0.01, // u of the wall's face, which the toe's back lies on
  clearGuard: 0.023, // u the plate keeps out past above the lip (the guard's face 0.015, the lens face 0.02)
  clearLip: 0.033, // ...and past at the lip (its tip 0.03)
  lipY: [0.015, 0.02], // the lip's underside and top, in part-local y (the deck is at 0.02)
  toeTop: -0.025, // where the plate steps in to the toe: clear below the axle heads (part-local y)
  bottom: -0.07, // the toe's foot
  bolts: [-0.06, -0.035], // its two bolts into the wall
  back: 0.046, // u of the plate's back edge, behind the housing's holes (0.031)
}

// The bracket's pieces. Each takes u2z, which maps u (outward from the bed edge) to part-local z on the side the
// piece is drawn on, so a reflector across the bed can draw the same bracket mirrored.

// a hex bolt head along `axis`
function photoeyeHex(g, axis, center) {
  return g.lathe([[0, 0], [0.0065, 0], [0.0065, 0.004], [0, 0.004]], { axis, center, segments: 6, smooth: false })
}

// the side plate in the x plane [x0, x0 + gauge], from yTop down; its face nearest the bed at uIn above the lip
function photoeyeSidePlate(g, x0, yTop, uIn, u2z) {
  const B = PHOTOEYE_BRACKET
  return g.extrude([
    [yTop, uIn], [yTop, B.back], [B.bottom, B.back], [B.bottom, B.wall + B.gauge], [B.toeTop, B.wall + B.gauge], [B.toeTop, B.clearLip],
    [B.lipY[1] + 0.003, B.clearLip], [B.lipY[1] + 0.003, uIn],
  ].map(([y, u]) => [y, u2z(u)]), x0, x0 + B.gauge, { axis: 'x' })
}

// the toe across [x0, x0 + width], its back on the wall
function photoeyeToe(g, x0, u2z) {
  const B = PHOTOEYE_BRACKET
  return g.box([B.width, B.toeTop - B.bottom, B.gauge], [x0 + B.width / 2, (B.bottom + B.toeTop) / 2, (u2z(B.wall) + u2z(B.wall + B.gauge)) / 2])
}

// the toe's two bolts into the wall, at x
function photoeyeToeBolts(g, x, u2z) {
  const B = PHOTOEYE_BRACKET
  return B.bolts.map((y) => g.lathe([[0, 0], [0.0065, 0], [0.0065, 0.004], [0, 0.004]], {
    axis: 'z', center: [x, y, Math.min(u2z(B.wall + B.gauge), u2z(B.wall + B.gauge + 0.004))], segments: 6, smooth: false,
  }))
}

// The housing and its bracket, as geometry() returns them. Materials: body, black (plug, cap), lens (window),
// pot, steel (the bracket).
function photoeyeHousing(g) {
  const X = PHOTOEYE.halfX, BACK = PHOTOEYE.back, FRONT = PHOTOEYE.front, Y0 = PHOTOEYE.bodyY0, Y1 = PHOTOEYE.bodyY1
  const CH = 0.024 // the chamfer across the lower back corner
  // the housing: its side profile (y, z) run across the width, with two mounting holes through it
  const body = g.extrude(
    [[Y0, BACK + CH], [Y0, FRONT], [Y1, FRONT], [Y1, BACK], [Y0 + CH, BACK]],
    -X, X,
    { axis: 'x', bevel: 0.0015, holes: [circle(Y0 + 0.012, FRONT - 0.011, 0.0042), circle(Y1 - 0.012, FRONT - 0.011, 0.0042)] },
  )
  // the lens window on the face, the beam height inside it
  const lens = g.extrude(rrect(-0.017, 0.062, 0.017, 0.114, 0.004), FRONT, FRONT + 0.0008, { bevel: 0.0003 })
  // the top cap, stopping short of the face, and the sensitivity pot in it
  const cap = g.bevelBox([2 * X, 0.005, FRONT - 0.004 - BACK], [0, Y1 + 0.0025, (BACK + FRONT - 0.004) / 2], 0.001, ['y-'])
  const pot = g.lathe([[0, 0], [0.0055, 0], [0.0055, 0.0038], [0.0047, 0.0045], [0, 0.0045]], { axis: 'y', center: [0, Y1 + 0.005, -0.012], segments: 20 })
  const slot = g.box([0.008, 0.0008, 0.0012], [0, Y1 + 0.0096, -0.012])
  // the M8 plug under the housing: a turned body and a hex coupling nut
  const PZ = (BACK + CH + FRONT) / 2
  const plug = g.lathe([[0, 0], [0.0048, 0], [0.0052, 0.0005], [0.0052, 0.009], [0.0056, 0.009], [0.0056, 0.019], [0.0068, 0.022], [0.0068, Y0], [0, Y0]], { axis: 'y', center: [0, 0, PZ], segments: 20 })
  const nut = g.lathe([[0, 0.009], [0.0072, 0.009], [0.0072, 0.018], [0, 0.018]], { axis: 'y', center: [0, 0, PZ], segments: 6, smooth: false })
  // the bracket (PHOTOEYE_BRACKET): a side plate profiled round the rail's guard and lip, a toe bolted to its wall,
  // and a hex bolt head through each of the housing's holes
  const BT = PHOTOEYE_BRACKET.gauge, BW = PHOTOEYE_BRACKET.width
  const U2Z = (u) => FRONT + 0.02 - u // this side: z falls as u grows
  const HZ = FRONT - 0.011 // the housing's holes
  const bracket = g.merge(
    photoeyeSidePlate(g, X, Y1 - 0.002, PHOTOEYE_BRACKET.clearGuard, U2Z), photoeyeToe(g, X, U2Z), ...photoeyeToeBolts(g, X + BW * 0.62, U2Z),
    photoeyeHex(g, 'x', [X + BT, Y0 + 0.012, HZ]), photoeyeHex(g, 'x', [X + BT, Y1 - 0.012, HZ]),
  )
  const both = { doubleSided: true }
  return [
    Object.assign({ desc: body, material: 'body' }, both),
    Object.assign({ desc: lens, material: 'lens' }, both),
    Object.assign({ desc: g.merge(cap, slot, plug, nut), material: 'black' }, both),
    Object.assign({ desc: pot, material: 'pot' }, both),
    Object.assign({ desc: bracket, material: 'steel' }, both),
  ]
}

definePart({
  lamps: ['led'],
  params: {
    maxRange: { type: 'number', default: 2, min: 0.1, max: 10, step: 0.05, label: 'Max range (m)', desc: 'How far down the beam a target still counts as present. The beam is cast along local +Z, so aim the sensor by rotating it; snapping it onto a conveyor guard fits this range across the lane for you.' },
    mode: {
      type: 'enum', default: 'diffuse', label: 'Sensing mode',
      desc: 'How the eye is installed. Diffuse: the target itself reflects the light back to the eye, so nothing stands opposite it. Retro-reflective: the eye looks at a reflector on the far side of the lane and a target breaking that beam is detected; the reflector is drawn at Max range, so snapping the eye onto a conveyor guard puts it on the far guard. In the sim both detect the same way: a target in the beam before Max range.',
      options: [
        { value: 'diffuse', label: 'Diffuse' },
        { value: 'retro', label: 'Retro-reflective' },
      ],
    },
    showBeam: { type: 'boolean', default: true, label: 'Show beam', desc: 'Draw the beam line in the viewport. A viewing aid only - hiding it does not change what the sensor detects.' },
    normallyClosed: { type: 'boolean', default: false, label: 'Normally closed (inverts the signal)', desc: 'Invert the output, so the tag reads true when NOTHING is detected. The beam colour still follows the real detection, not the inverted signal.' },
    mark: { type: 'string', suggest: 'marks', default: '', label: 'Only marked targets', desc: 'Count a target only if a machine upstream left this mark on it (wrapped, or a label a labeller wrote). Empty: anything in the beam counts. This is how a program checks a product, not just its presence - a load that was never wrapped reads as clear.' },
    tag: { type: 'tag', dir: 'out', stType: 'BOOL', default: '', label: 'Presence tag', group: 'Comms', desc: 'Where the photoeye publishes presence for the program to read. Whether true means blocked or clear is set by Normally closed above.' },
  },
  // The housing, drawn: a body with a chamfered lower back and two mounting holes, the lens window on the face,
  // a top cap with a sensitivity pot, and an M8 plug underneath. Part-local metres, front (+Z) = the beam.
  geometry(g, p) {
    const out = photoeyeHousing(g)
    // RETRO-REFLECTOR at the beam's far end, the eye's mirror image across the bed. A guard mount fits maxRange to
    // the bed's width plus the lens's 20 mm stand-off at BOTH edges, so the reflector's face lands 20 mm out from the
    // far bed edge, outside that guard as the eye is outside its own, and its bracket is the eye's, mirrored: the same
    // side plate round that rail's guard and lip, the same toe on its wall. Its own submeshes, so the housing's still
    // pool across every copy whatever their ranges.
    if (p.mode === 'retro') {
      const BT = PHOTOEYE_BRACKET.gauge, BW = PHOTOEYE_BRACKET.width
      const F = PHOTOEYE.front + (typeof p.maxRange === 'number' && p.maxRange > 0 ? p.maxRange : 2) // the face, at far u 0.02
      const FU2Z = (u) => F - 0.02 + u // far side: z grows with u
      const E = PHOTOEYE.emitY, RR = 0.025, RT = 0.008 // the beam height, the disc's radius and thickness
      const disc = g.lathe([[0, 0], [RR - 0.002, 0], [RR, 0.002], [RR, RT], [0, RT]], { axis: 'z', center: [0, E, F], segments: 24 })
      const rim = g.lathe([[RR, 0.001], [RR + 0.003, 0.001], [RR + 0.003, RT + 0.001], [RR, RT + 0.001]], { axis: 'z', center: [0, E, F], segments: 24 })
      // the plate behind the disc, and the side plate it is bent from at its +X edge
      const PX0 = -0.032, PX1 = 0.058, PH = 0.032, UP = 0.02 + RT // u of the plate's face
      const plate = g.box([PX1 - PX0, 2 * PH, BT], [(PX0 + PX1) / 2, E, FU2Z(UP + BT / 2)])
      const rbracket = g.merge(
        rim, plate, photoeyeSidePlate(g, PX1 - BT, E + PH, UP, FU2Z), photoeyeToe(g, PX1 - BW, FU2Z), ...photoeyeToeBolts(g, PX1 - BW * 0.62, FU2Z),
        photoeyeHex(g, 'z', [0, E, FU2Z(UP + BT)]),
      )
      const both = { doubleSided: true }
      out.push(Object.assign({ desc: disc, material: 'reflector' }, both))
      out.push(Object.assign({ desc: rbracket, material: 'steel' }, both))
    }
    return out
  },
  react(ctx) {
    // the host casts the beam out to the maxRange param (its rangeParam); the gate below keeps that explicit
    const s = ctx.sense('lens')
    const want = ctx.params.mark
    const present = s.hit && s.distance <= ctx.params.maxRange && (!want || (!!s.marks && !!s.marks[want]))
    // a PLC that drives this tag is watching a real eye (Watch only): the LED shows what that eye reports
    if (ctx.params.tag && ctx.tagDriven(ctx.params.tag)) {
      ctx.lamps.led = ctx.readTag(ctx.params.tag) !== !!ctx.params.normallyClosed
      return
    }
    ctx.lamps.led = present // raw presence, not the NC-inverted output
    let out = present
    if (ctx.params.normallyClosed) out = !out // NC: de-energized (no cargo) reads true
    if (ctx.params.tag) ctx.writeTag(ctx.params.tag, out)
  },
})

// Push Button — an illuminated, depressable pushbutton. It reacts to a user "use"/click (ctx.used()),
// depresses the cap into the housing (ctx.setSubPose — a −Z travel, the button front is +Z), lights the cap's
// emissive face (ctx.lamps), and drives a PLC tag. Two modes: momentary (default) holds pressed for a 0.3 s
// pulse of SIM time (not wall-clock); maintained latches on each use. The written output is 'pressed XOR
// normallyClosed' (a normally-closed contact reads true at rest).
//
// The LAMP is its own circuit, not a side effect of the press. On real 22 mm gear the light block is a
// separate module stacked behind the operator with its own terminals and often its own voltage, wired
// independently of the contact blocks - making the lamp echo the press is something you do deliberately by
// strapping a contact to it, not what the device does by itself. So the source is DECLARED ('lampSource'),
// never inferred from whether a tag happens to be bound: follows-press (kept as the default, so a freshly
// placed button still visibly lights), a PLC tag (the acknowledge wiring a real panel uses), always-on (a
// power-on indicator), or unlit (no light block fitted). Inferring it from the binding would make echo the
// fallback, the wiring you would least often choose, and could not express a plain unlit button or a lamp lit by
// anything other than this button's own press.
//
// An EMERGENCY STOP is this device with a different operator, not a different part: 'emergencyStop' swaps the
// cap for a red mushroom head in a yellow shroud on a yellow lid, and FIXES the two things an E-stop may not be set to -
// it latches when struck and stays in until released, and its contact is normally closed, so a broken wire stops the line the same way a press does. The Inspector hides the settings
// it overrides (visibleWhen) rather than showing switches that do nothing.
//
// The release is a TWIST, and is drawn as one: the next Use turns the struck head clockwise (the way the arrow on
// its face points) while it is still held in, then the head springs out and turns back. The contact recloses at
// the spring-out, not at the Use - the line cannot see an E-stop released before the head is.
//
// Built in code (geometry()): the housing, mounting tabs, bezel, legend plate and slotted bolt heads on the part
// root, and the cap on the `cap` link - which the press moves (ctx.setSubPose) - as a LAMP submesh
// (MeshPart.lamp), tinted by the `buttonColor` param and lit via ctx.lamps. The shapes are kept in NATIVE units:
// geometry() scales them uniformly to
// PUSH_BUTTON_HEIGHT tall (x/z centred on the whole model, base at y 0), so the face label, the mount and the
// demo's back-plate offset are all that scale's numbers.
//
// This is the part's source. `npm run build-parts` writes behavior.ts (this script as the app ships it, with the
// _shared/ modules it imports joined in and `manifest` / `rig()` left out) and rig.json (the manifest, with the
// rig compiled from rig()).

// The station box's height, which sets the size of everything: 0.09 m makes the box ~90 mm square, the round
// cap ~28 mm across (a 22 mm operator's) and the E-stop head 40 mm, the sizes of real gear.
const PUSH_BUTTON_HEIGHT = 0.09
const RED_LIT = [1, 0.15, 0.12] // pre-refresh seed for the lit colour (the param takes over on first refresh)
const BUTTON_COLOR_DEFAULT = '#b3140f' // the classic matte red cap

const PRESS_DEPTH = 0.01 // m, cap travel into the housing
// A mushroom head's travel. A real 40 mm head moves a few millimetres; this is more, because a press has to be SEEN
// going in and coming out from station distance - at 8 mm on a 0.1 m head it read as never retracting at all.
const ESTOP_PRESS_DEPTH = 0.007 // m
const ESTOP_MOVE_S = 0.1 // s the head takes to go in or come out: quick, but a motion rather than a one-tick jump
// Timed like a hand on a spring-loaded head, and tuned by eye in both places it plays: the running sim, where the
// head must come out promptly after a Use (0.8 s read as sluggish), and a stopped scene's Use, where a twist has
// to last long enough to be seen at all (0.35 s, linear, is over before anyone notices it turn).
const TWIST_S = 0.5 // s of sim time the release twist takes, the head still held in
const SPRING_S = 0.2 // s for the released head to turn back to rest
const TWIST_RAD = 0.75 // how far the head turns to release, ~43 degrees
// The cap link's origin is the part's, at the back plate's foot, while the head turns about its OWN axis, which
// stands this high above it - so a turn is paired with the offset that keeps that axis where it is.
const HEAD_AXIS_Y = PUSH_BUTTON_HEIGHT / 2
const PULSE_S = 0.3 // momentary hold window, seconds of sim time

let pressed = false
let pulseTicks = 0 // remaining momentary window, in whole sim ticks (exact — no float drift)
let twistTicks = 0 // remaining release twist, in sim ticks; while it runs the head is turning and still in
let springTicks = 0 // remaining spring-back after the head is out
let headDepth = 0 // the E-stop head's drawn depth, eased toward in/out; the CONTACT follows pressed at once

definePart({
  interactive: true, // makes the part show a "Use" prompt + routes the click to ctx.used()
  lamps: ['cap'],
  params: {
    emergencyStop: { type: 'boolean', default: false, label: 'Emergency stop (mushroom head)', desc: 'A red mushroom head on a yellow station that latches when struck and stays in until it is used again, like twisting a real E-stop out. Its contact is always normally closed, so the tag reads true while the stop is released and false while it is in.' },
    text: { type: 'string', default: 'STOP', label: 'Face label', group: 'Face', desc: 'The legend plate above the button, the way a lamacoid is mounted. Keep it short enough to read at station distance.' },
    buttonColor: { type: 'color', default: BUTTON_COLOR_DEFAULT, visibleWhen: { param: 'emergencyStop', is: false }, label: 'Button color', group: 'Face', desc: 'Tint of the cap, and of the lamp when it lights.' },
    momentary: { type: 'boolean', default: true, visibleWhen: { param: 'emergencyStop', is: false }, label: 'Momentary (else maintained latch)', desc: 'On, each press is a fixed 0.3 s pulse of sim time, like a spring-return start button - so a paused sim holds the pulse rather than letting it expire. Off, the button latches on one press and releases on the next, like a maintained selector.' },
    startPressed: { type: 'boolean', default: false, visibleWhen: { param: 'emergencyStop', is: false }, label: 'Starts pressed (maintained only)', group: 'Start state', desc: 'A maintained button starts latched in, so a run begins with it pressed. A momentary button springs back on its own, so it ignores this.' },
    startStruck: { type: 'boolean', default: false, visibleWhen: { param: 'emergencyStop', is: true }, label: 'Starts struck', group: 'Start state', desc: 'The emergency stop starts latched in, so a run begins with the stop open - the way to check that a line refuses to start until it is twisted out.' },
    normallyClosed: { type: 'boolean', default: false, visibleWhen: { param: 'emergencyStop', is: false }, label: 'Normally closed (inverts the signal)', desc: 'Invert the output, so the tag reads true while the button is NOT pressed - the safety convention for a stop button, where a broken wire reads the same as a press.' },
    lampSource: {
      type: 'enum', default: 'press', label: 'Lamp source',
      desc: 'What lights the cap. Follows press echoes this button, the way a contact strapped to the light block would. PLC tag hands the lamp to the program through Lamp tag below - the acknowledge wiring a real panel uses. Always on is a power-on indicator. Unlit is a button with no light block fitted.',
      options: [
        { value: 'press', label: 'Follows press' },
        { value: 'tag', label: 'PLC tag' },
        { value: 'on', label: 'Always on' },
        { value: 'off', label: 'Unlit' },
      ],
    },
    tag: { type: 'tag', dir: 'out', stType: 'BOOL', default: '', label: 'Button output tag', group: 'Comms', desc: 'Where the button publishes its press for the program to read. Whether true means pressed or at-rest is set by Normally closed above.' },
    lampTag: { type: 'tag', dir: 'in', stType: 'BOOL', default: '', label: 'Lamp tag (PLC lights the cap)', group: 'Comms', desc: 'Which PLC bool lights the cap, so the program can acknowledge a press rather than just echo it. Read only when Lamp source above is set to PLC tag; left unbound there, the lamp stays dark like an unwired light block.' },
  },
  // The button, drawn. Shapes are in NATIVE units (the face is the x-y plane, +z out of the panel) and mapped to
  // metres by a uniform scale to PUSH_BUTTON_HEIGHT tall, x/z centred on the whole model, base at y 0.
  geometry(g, p) {
    var S = PUSH_BUTTON_HEIGHT / 0.4248, CZ = 0.14225, Y0 = -0.2124
    // native → metres: the fitHeight normalisation (uniform scale, x/z centred on the whole model, base at y 0)
    var fit = function (parts) { return g.transform(g.merge.apply(g, parts), { scale: S, translate: [0, -Y0 * S, -CZ * S] }) }
    var estop = !!p.emergencyStop
    var gray = [], dark = [], light = [], bolt = [], yellow = []
    // housing: the body, and the slightly larger front frame the face sits in. An emergency stop station is the
    // same box with a YELLOW lid on the grey base (the usual emergency-stop station shape), so the frame changes colour
    gray.push(g.bevelBox([0.4028, 0.4028, 0.1759], [0, 0, 0.08795], 0.0036))
    ;(estop ? yellow : gray).push(g.bevelBox([0.4248, 0.4248, 0.0477], [0, 0, 0.19975], 0.0035))
    // the mounting tabs behind it: round-cornered plates, two round holes each
    var arc = function (cy, a0) {
      var pts = []
      for (var k = 0; k <= 2; k++) { var a = a0 + (k * Math.PI) / 4; pts.push([0.2323 + 0.0088 * Math.cos(a), cy + 0.0088 * Math.sin(a)]) }
      return pts
    }
    var tab = [[0.1832, -0.1898]].concat(arc(-0.181, -Math.PI / 2), arc(0.181, 0), [[0.1832, 0.1898]])
    var hole = function (cy) {
      var pts = []
      for (var k = 0; k < 8; k++) pts.push([0.2246 + 0.0114 * Math.cos((k * Math.PI) / 4), cy + 0.0114 * Math.sin((k * Math.PI) / 4)])
      return pts
    }
    for (var sx = -1; sx <= 1; sx += 2) {
      var mx = function (pts) { return pts.map(function (q) { return [sx * q[0], q[1]] }) }
      gray.push(g.extrude(mx(tab), -0.0073, 0, { holes: [mx(hole(0.1632)), mx(hole(-0.1632))] }))
    }
    // the dark bezel round the cap: a lip, a step, a raised collar and the socket the cap sits in
    dark.push(g.lathe([[0.0985, 0.2236], [0.0985, 0.2344], [0.0822, 0.2344], [0.0822, 0.2494], [0.072, 0.2494], [0.072, 0.1537], [0, 0.1537]], { axis: 'z' }))
    // the light legend plate across the upper face, arched round the bezel. An E-stop has none: its yellow lid is
    // the background, and the caption stands on the lid itself
    var arch = [[-0.1052, -0.0008], [-0.0939, 0.0404], [-0.0744, 0.075], [-0.0413, 0.0973], [0, 0.1051], [0.0413, 0.0973], [0.0744, 0.075], [0.0939, 0.0404], [0.1052, -0.0008]]
    if (!estop) light.push(g.extrude([[-0.1391, -0.0008], [-0.1391, 0.1627], [0.1391, 0.1627], [0.1391, -0.0008]].concat(arch.slice().reverse()), 0.2236, 0.2285))
    // the four slotted bolt heads: an octagon split by a screwdriver slot, each turned its own way
    var heads = [[0.1756, 0.175, 26.2], [-0.1756, 0.175, -17.2], [-0.1756, -0.175, 65.3], [0.1756, -0.175, -39.2]]
    for (var bi = 0; bi < heads.length; bi++) {
      var hc = heads[bi], th = (hc[2] * Math.PI) / 180, R = 0.0177, GAP = 0.00074
      var oct = []
      for (var ok = 0; ok < 8; ok++) oct.push([R * Math.cos((ok * Math.PI) / 4), R * Math.sin((ok * Math.PI) / 4)])
      for (var half = -1; half <= 1; half += 2) {
        // the octagon clipped to one side of the slot (local x = ±GAP), then turned and placed
        var clip = []
        for (var ci = 0; ci < 8; ci++) {
          var P = oct[ci], Q = oct[(ci + 1) % 8], pin = half * P[0] >= GAP, qin = half * Q[0] >= GAP
          if (pin) clip.push(P)
          if (pin !== qin) { var tt = (half * GAP - P[0]) / (Q[0] - P[0]); clip.push([half * GAP, P[1] + tt * (Q[1] - P[1])]) }
        }
        var placed = clip.map(function (q) { return [hc[0] + q[0] * Math.cos(th) - q[1] * Math.sin(th), hc[1] + q[0] * Math.sin(th) + q[1] * Math.cos(th)] })
        bolt.push(g.extrude(placed, 0.2171, 0.2301))
      }
    }
    // the cap: a short round plunger with a chamfered edge, on the link the press moves
    var cap, arrow = []
    if (!estop) {
      cap = [g.lathe([[0.0673, 0.2032], [0.0673, 0.2883], [0.0638, 0.2918], [0, 0.2918]], { axis: 'z' })]
    } else {
      // An E-stop operator: a 40 mm turn-to-release head on its station (radius 0.0944 in these native units), a
      // yellow SHROUD standing out of the bezel (static - it is the operator's body), a red NECK out of the shroud,
      // and a flat-faced head about twice the neck across with a rounded front edge. The head's back stands 0.05
      // off the shroud (the red neck showing between them, as on the real thing), so its 0.033 of travel -
      // ESTOP_PRESS_DEPTH, in these native units - never meets it. Turned smooth and in more segments than the
      // plunger, because a disc facing the camera shows every facet.
      yellow.push(g.lathe([[0.075, 0.2236], [0.075, 0.272], [0.071, 0.28], [0.052, 0.28], [0.052, 0.2236]], { axis: 'z', segments: 40 }))
      cap = [
        g.lathe([[0.05, 0.2032], [0.05, 0.33], [0, 0.33]], { axis: 'z', segments: 32 }),
        g.lathe([[0.05, 0.33], [0.085, 0.33], [0.0928, 0.336], [0.0944, 0.346], [0.0944, 0.376], [0.0913, 0.385], [0.0842, 0.39], [0, 0.39]], { axis: 'z', segments: 48 }),
      ]
      // the TWIST-TO-RELEASE arrow printed on the face: a band round most of a circle, open at the top, and an
      // arrowhead at its upper-left end pointing the way the head turns out (clockwise, seen from the front). It is
      // WHITE rather than embossed red: on a plain round head it is the only thing that shows the head turning
      var AR = 0.0456, AW = 0.0055, A0 = (70 * Math.PI) / 180, A1 = (-250 * Math.PI) / 180, band = [], n = 28
      for (var ai = 0; ai <= n; ai++) { var aa = A0 + ((A1 - A0) * ai) / n; band.push([(AR + AW) * Math.cos(aa), (AR + AW) * Math.sin(aa)]) }
      for (var aj = n; aj >= 0; aj--) { var ab = A0 + ((A1 - A0) * aj) / n; band.push([(AR - AW) * Math.cos(ab), (AR - AW) * Math.sin(ab)]) }
      arrow.push(g.extrude(band, 0.3895, 0.396))
      var tipA = A1 - (22 * Math.PI) / 180, HW = AW * 2.6
      arrow.push(g.extrude([
        [(AR + HW) * Math.cos(A1), (AR + HW) * Math.sin(A1)],
        [AR * Math.cos(tipA), AR * Math.sin(tipA)],
        [(AR - HW) * Math.cos(A1), (AR - HW) * Math.sin(A1)],
      ], 0.3895, 0.396))
    }

    var both = { doubleSided: true }
    return [
      Object.assign({ desc: fit(gray), material: 'gray' }, both),
      Object.assign({ desc: fit(dark), material: 'dark' }, both),
      Object.assign({ desc: fit(light), material: 'light' }, both),
      Object.assign({ desc: fit(bolt), material: 'bolt' }, both),
    ].concat(estop ? [Object.assign({ desc: fit(yellow), material: 'yellow' }, both), { desc: fit(arrow), link: 'cap', material: 'light' }] : []).concat([
      // an E-stop head is red whatever Button color says, so it carries no colorParam
      estop
        ? { desc: fit(cap), link: 'cap', material: 'cap', lamps: [{ name: 'cap', emissive: RED_LIT }] }
        : { desc: fit(cap), link: 'cap', material: 'cap', lamps: [{ name: 'cap', emissive: RED_LIT }], colorParam: 'buttonColor' },
    ])
  },
  // The authored starting state, set before the first step: a maintained button may start latched in, an E-stop
  // struck. A press changes it from there; only these params say where a run (or a stopped Use) starts.
  init(ctx) {
    const estop = !!ctx.params.emergencyStop
    pressed = estop ? !!ctx.params.startStruck : !ctx.params.momentary && !!ctx.params.startPressed
    headDepth = estop && pressed ? -ESTOP_PRESS_DEPTH : 0
  },
  step(ctx) {
    const estop = ctx.params.emergencyStop
    let turn = 0 // the head's twist, radians about its own axis (clockwise seen from the front is negative)
    if (estop) {
      pulseTicks = 0
      const twistN = Math.ceil(TWIST_S / ctx.dt), springN = Math.ceil(SPRING_S / ctx.dt)
      if (ctx.used() && twistTicks === 0) {
        if (!pressed) { pressed = true; springTicks = 0 } // struck: in, and latched
        else twistTicks = twistN // twisted to release: the head turns first, still in
      }
      if (twistTicks > 0) {
        twistTicks--
        const u = 1 - twistTicks / twistN
        turn = -TWIST_RAD * u * (2 - u) // eased out: it answers the Use at once and slows into the release
        if (twistTicks === 0) { pressed = false; springTicks = springN } // turned far enough: out it springs
      } else if (springTicks > 0) {
        springTicks--
        const v = springTicks / springN
        turn = -TWIST_RAD * v * v // eased out: the spring is quick off the mark and settles into rest
      }
    } else if (ctx.params.momentary) {
      if (ctx.used()) pulseTicks = Math.ceil(PULSE_S / ctx.dt)
      pressed = pulseTicks > 0
      if (pulseTicks > 0) pulseTicks--
      twistTicks = springTicks = 0
    } else {
      if (ctx.used()) pressed = !pressed
      pulseTicks = twistTicks = springTicks = 0
    }
    // The lamp runs off its DECLARED source (see the header) - the press is only one of the four wirings,
    // not the fallback. A 'tag' source with no Lamp tag named reads dark, like a light block nobody wired.
    // The cap depress follows pressed under every source.
    const src = ctx.params.lampSource
    const litByTag = !!ctx.params.lampTag && ctx.readTag(ctx.params.lampTag)
    // a PLC that drives this tag is watching a real button (Watch only): show it as that button reads
    const shown = ctx.params.tag && ctx.tagDriven(ctx.params.tag) ? ctx.readTag(ctx.params.tag) !== (estop || ctx.params.normallyClosed) : pressed
    ctx.lamps.cap = src === 'on' ? true : src === 'off' ? false : src === 'tag' ? litByTag : shown
    let depth = shown ? -PRESS_DEPTH : 0
    if (estop) {
      const target = shown ? -ESTOP_PRESS_DEPTH : 0
      const stepM = (ESTOP_PRESS_DEPTH * ctx.dt) / ESTOP_MOVE_S
      headDepth = Math.abs(target - headDepth) <= stepM ? target : headDepth + Math.sign(target - headDepth) * stepM
      depth = headDepth
    } else headDepth = 0
    ctx.setSubPose('cap', turn === 0
      ? { position: [0, 0, depth] }
      : { position: [HEAD_AXIS_Y * Math.sin(turn), HEAD_AXIS_Y * (1 - Math.cos(turn)), depth], rotation: [0, 0, turn] })
    if (ctx.params.tag) ctx.writeTag(ctx.params.tag, pressed !== (estop || ctx.params.normallyClosed))
  },
})

// Stack Light — a parametric 1-8 segment signal tower. Each segment is an emissive lens lamp; one integer
// bitmask lights them — bit i (LSB = the bottom segment) lights segment i+1, colours cycling bottom-up
// green → amber → red → blue → white. The bitmask comes from a PLC INT tag while a program actually DRIVES it
// (ctx.tagDriven); any other time the authored 'value' param drives the same lamps. Bits above the
// segment count are masked off. Use/click is a LAMP TEST: every tier lights briefly, then the pattern returns.
//
// The tower: a black housing (foot + stem + base collar + seam rings + floating cap under a low cone roof)
// carrying 1-8 tinted lens tiers around a pale inner core. 'segments' drives the tower height: the cap, core,
// seam rings and the hidden collision shell all track it.
//
// Per-tier links (not array-links): each lens needs its own emissive colour + lamp name, which an array's
// shared shape can't express, so all 8 are built and the unused ones collapse out of sight (see `tier`).
// That costs no draws: the host folds same-shape lamp links into ONE instanced lamp bank
// (src/render/parts/lampBank.ts), so the 8 tiers are a single draw however many are in use.
//
// This is the part's source. `npm run build-parts` writes behavior.ts (this script as the app ships it, with the
// _shared/ modules it imports joined in and `manifest` / `rig()` left out) and rig.json (the manifest, with the
// rig compiled from rig()).

// ---- geometry (primitive cylinders) ------------------------------------------------------------------------
const MAX_SEGS = 8
const DEF_SEGS = 3

const LAMPS = ['seg1', 'seg2', 'seg3', 'seg4', 'seg5', 'seg6', 'seg7', 'seg8']
// How long a lamp test holds. Keep it under half a second: the stopped editor's C preview (sim/idlePose.ts
// recordPress) stops watching a press after 30 still ticks, and a test still lit then reads as a LATCH, which
// the preview answers with a second press.
const LAMP_TEST_S = 0.4
let test = 0 // seconds of lamp test left

definePart({
  interactive: true, // Use/click runs a lamp test
  lamps: LAMPS,
  params: {
    segments: { type: 'number', default: DEF_SEGS, min: 1, max: MAX_SEGS, step: 1, label: 'Tiers', desc: 'How many lamp tiers are stacked. Colours are fixed and cycle bottom-up: green, amber, red, blue, white.' },
    value: { type: 'number', bits: 'segments', default: 1, min: 0, max: 255, step: 1, label: 'Lit tiers', group: 'Start state', desc: 'Which tiers are lit, one box per tier, the BOTTOM tier first (bit 0 of the bitmask the tag carries: 1 lights green, 2 amber, 3 both). Bits above the segment count are masked off. A program driving the tag below replaces this value.' },
    // autoWhenDriven: this tag COMMANDS the lamps (the step's auto gate reads it), so a program driving it
    // owns the device — the pilot prompt shows "In auto - PLC controlled" instead of a dead "Use".
    tag: { type: 'tag', dir: 'in', stType: 'INT', autoWhenDriven: true, setpointFor: 'value', default: '', label: 'Lamp bitmask tag', group: 'Comms', desc: 'The program writes the lit-tier bitmask here. While it drives the tag it OWNS the light, so the Value field above becomes a read-only readout and a hand Use is refused with "In auto - PLC controlled".' },
  },
  step(ctx) {
    const segs = Math.min(MAX_SEGS, Math.max(1, Math.round(ctx.params.segments)))
    const all = (1 << segs) - 1
    // Output ownership (ctx.tagDriven): the tag lights the lamps only while a controller actually drives it —
    // gating on the tag NAME instead would pin the tower to a dead tag the moment one was typed. Release falls
    // back to the authored pattern instead of freezing the last commanded one (right for an indicator).
    const auto = ctx.tagDriven(ctx.params.tag)
    // Use = a lamp test, in hand mode only: while a program drives the tag it owns the light, and the press is
    // refused ("In auto - PLC controlled"). It never changes the pattern — that is the Value field's, or the PLC's.
    if (ctx.used() && !auto) test = LAMP_TEST_S
    test = Math.max(0, test - ctx.dt)
    const v = (auto ? ctx.readNumber(ctx.params.tag) : Math.round(ctx.params.value)) & all // mask to the segment count
    ctx.report('value', v) // the pattern (masked), which is what 'value' means; a lamp test doesn't change it
    const lit = test > 0 ? all : v
    for (let i = 0; i < LAMPS.length; i++) ctx.lamps[LAMPS[i]] = i < segs && ((lit >> i) & 1) === 1
  },
})

stProgram:
(* Delta transfer cell: one carton at a time from infeed A to outfeed B.

   Escapement (column clear):
     A1 accumulates the queue against the blade (BladeUp). A2, the pick belt, runs faster (0.6 vs 0.4 m/s).
     The blade drops only when the pick lane on A2 is empty (EyeGate, EyeZone, EyeStop clear) AND the robot is clear
     of the infeed column (TCP over belt B or above 250 mm). The released carton accelerates on A2 and opens a gap to
     the next one; EyeHead (20 mm upstream of the blade) sees that gap, A1 stops at once, the blade rises in the gap,
     and A1 runs again once the blade is up. The carton runs on to the fixed end stop under the robot.
   Robot (delta part handshake, the same as the DuoPod part: RobotCmd row, rising RobotExecute, RobotDone/RobotPoint):
     ready (1) -> wait carton settled at the stop -> pick (2) -> vacuum, wait VacuumOk ->
     wait the belt-B drop zone clear (EyeB0, EyeB1) -> place (3) -> vacuum off, wait release -> ready (1).
   Supervision: ColumnAlarm latches if the blade is ever open while the TCP is low over the infeed column (the
   interlock above failed); it stops the line like an E-stop and START clears it.
   Safety: the E-stop contact (EStopOk, normally closed) drops RobotEnable (the robot holds where it is, vacuum kept so the carton is not dropped), stops every
   belt and the feed, and latches Running off; START restarts. Stack light: green running, amber stopped, red E-stop. *)
VAR_INPUT
        StartPB : BOOL;
        EStopOk : BOOL;
        EyeStop : BOOL;
        EyeZone : BOOL;
        EyeGate : BOOL;
        EyeHead : BOOL;
        EyeFull : BOOL;
        EyeB0 : BOOL;
        EyeB1 : BOOL;
        RobotDone : BOOL;
        RobotBusy : BOOL;
        RobotPoint : INT;
        VacuumOk : BOOL;
        RobotX : REAL;
        RobotZ : REAL;
        Delivered : INT;
END_VAR
VAR_OUTPUT
        BeltA1Run : BOOL;
        BeltA2Run : BOOL;
        BeltBRun : BOOL;
        FeedRun : BOOL;
        BladeUp : BOOL := TRUE;
        RobotCmd : INT;
        RobotExecute : BOOL;
        Vacuum : BOOL;
        RobotEnable : BOOL;
        StackLight : INT;
        Running : BOOL;
        Releasing : BOOL;
        Step : INT;
        Picked : INT;
        ColumnAlarm : BOOL;
END_VAR
VAR
        A1Hold : BOOL;
        LaneEmpty : BOOL;
        RobotClear : BOOL;
        DropClear : BOOL;
        Settled : TON;
        BladeDelay : TON;
        BladeRise : TON;
        VacWait : TON;
        QueueFull : TON;
        Moving : BOOL;
END_VAR

(* ---------------------------------------------------------------- run / safety *)
IF StartPB THEN ColumnAlarm := FALSE; END_IF;
Running := (Running OR StartPB) AND EStopOk AND NOT ColumnAlarm;
(* motion only while latched running: releasing the E-stop alone must not restart the robot (ISO 13850), START does *)
RobotEnable := Running;
BeltA2Run := Running;
BeltBRun := Running;
(* queue full = a carton standing at EyeFull, not one passing it after the drop *)
QueueFull(IN := EyeFull, PT := T#1s);
FeedRun := Running AND NOT QueueFull.Q;
IF NOT EStopOk THEN
        StackLight := 4;
ELSIF Running THEN
        StackLight := 1;
ELSE
        StackLight := 2;
END_IF;

(* ---------------------------------------------------------------- escapement *)
LaneEmpty := NOT EyeGate AND NOT EyeZone AND NOT EyeStop;
RobotClear := (RobotX < 100.0) OR (RobotZ > 250.0);
IF Running AND BladeUp AND NOT A1Hold AND LaneEmpty AND RobotClear AND EyeHead THEN
        BladeUp := FALSE;
        Releasing := TRUE;
END_IF;
(* the gap reaches the head eye: hold A1, the next carton stops short of the blade *)
IF Releasing AND NOT EyeHead THEN
        A1Hold := TRUE;
        Releasing := FALSE;
END_IF;
(* the released carton's tail clears the blade line ~35 ms after the eye clears *)
BladeDelay(IN := A1Hold AND NOT BladeUp, PT := T#120ms);
IF BladeDelay.Q THEN
        BladeUp := TRUE;
END_IF;
BladeRise(IN := A1Hold AND BladeUp, PT := T#400ms);
IF BladeRise.Q THEN
        A1Hold := FALSE;
END_IF;
BeltA1Run := Running AND NOT A1Hold;
(* supervision: the blade open with the robot low over the infeed column *)
IF NOT BladeUp AND RobotX >= 100.0 AND RobotZ <= 250.0 THEN
        ColumnAlarm := TRUE;
END_IF;

(* ---------------------------------------------------------------- robot cycle *)
DropClear := NOT EyeB0 AND NOT EyeB1;
(* a carton at the stop spans z -0.12..0.13 and covers EyeZone too; one carton is released at a time *)
Settled(IN := EyeStop, PT := T#300ms);
VacWait(IN := (Step = 30) OR (Step = 50), PT := T#150ms);
CASE Step OF
        0:      (* idle: go to ready once running *)
                Vacuum := FALSE;
                IF Running AND RobotDone THEN
                        RobotCmd := 1; Moving := TRUE; Step := 10;
                END_IF;
        10:     (* to ready *)
                IF Moving AND RobotBusy THEN Moving := FALSE; END_IF;
                IF NOT Moving AND RobotDone AND RobotPoint = 1 THEN Step := 20; END_IF;
        20:     (* wait for a settled carton at the stop *)
                IF Running AND Settled.Q THEN
                        RobotCmd := 2; Moving := TRUE; Step := 25;
                END_IF;
        25:     (* down to pick *)
                IF Moving AND RobotBusy THEN Moving := FALSE; END_IF;
                IF NOT Moving AND RobotDone AND RobotPoint = 2 THEN Vacuum := TRUE; Step := 30; END_IF;
        30:     (* grip *)
                IF VacuumOk AND VacWait.Q THEN Step := 40; END_IF;
        40:     (* wait for the drop zone on belt B *)
                IF Running AND DropClear THEN
                        RobotCmd := 3; Moving := TRUE; Step := 45;
                END_IF;
        45:     (* transfer *)
                IF Moving AND RobotBusy THEN Moving := FALSE; END_IF;
                IF NOT Moving AND RobotDone AND RobotPoint = 3 THEN Vacuum := FALSE; Step := 50; END_IF;
        50:     (* release *)
                IF NOT VacuumOk AND VacWait.Q THEN
                        Picked := Picked + 1;
                        RobotCmd := 1; Moving := TRUE; Step := 10;
                END_IF;
END_CASE;
(* Execute is held from the command until the robot answers Busy: a one-scan pulse can fall between two part ticks *)
RobotExecute := Moving;
